function getCurrentUser() {
  // frappe/crm Vue app stores the logged-in user in the `user_id` cookie.
  // window.frappe.session.user is not exposed in this Vue app, so read the
  // cookie directly (matches frontend/src/stores/session.js).
  const cookies = new URLSearchParams(document.cookie.split('; ').join('&'))
  const u = cookies.get('user_id')
  return u === 'Guest' ? null : u
}

function getUserRoles() {
  // Frappe's boot object exposes the logged-in user's roles. The frappe-ui Vue
  // app inherits from Frappe's session/boot. Fall back to an empty set if the
  // boot payload isn't there yet (defensive — should always be populated by
  // the time a doctype modal renders).
  const roles = window.frappe?.boot?.user?.roles
  return new Set(Array.isArray(roles) ? roles : [])
}

class CRMQuoteRequest {
  onRender() {
    const currentUser = getCurrentUser()
    const userRoles = getUserRoles()
    const isLeadOwner = this.doc.lead_owner === currentUser
    // Privileged-user bypass mirrors Script 1's is_privileged check on the
    // server. Lets Admin / Sales Manager review / accept / request-revision
    // even when the lead has no Lead Owner assigned yet (common during
    // testing or when a lead is mid-handoff).
    const isPrivileged =
      currentUser === 'Administrator' ||
      userRoles.has('Administrator') ||
      userRoles.has('Sales Manager') ||
      userRoles.has('System Manager')
    const canReview = isLeadOwner || isPrivileged

    if (canReview) {
      // Lead Owner / privileged workflow:
      //   - Reviews the quote (file/value/margin etc., already read-only via
      //     permlevel + the explicit lock on quote_file below).
      //   - Picks Accepted or Revision Requested from the Status dropdown.
      //   - Clicks Update. Server-side scripts handle the rest.
      this.setFieldProperty('quote_file', 'read_only', true)
      return
    }

    // Estimation Team and everyone else: status is auto-managed by the Before
    // Validate server script (Pending -> Quote Received on file attach).
    // Hiding the dropdown prevents accidental manual changes.
    this.setFieldProperty('status', 'hidden', true)
  }
}

class CRMLead {
  onLoad() {
    // Seed the filter from whatever Source the lead already has when
    // the form opens (covers existing leads, not just new ones).
    this.setFieldProperty(
      'custom_sub_source',
      'link_filters',
      JSON.stringify({ source: this.doc.source || '' })
    )
  }

  source() {
    // Fires whenever the Source field changes. this.value is the new
    // value; setFieldProperty mutates the reactive fieldPropertyOverrides
    // map, which Field.vue's computed reads — Link.vue then reloads its
    // search_link dropdown with the new filter.
    this.setFieldProperty(
      'custom_sub_source',
      'link_filters',
      JSON.stringify({ source: this.value || '' })
    )
  }
}
